import { SkeletonRectangle } from "@/core/components/primitives/skeleton-rectangle/skeleton-rectangle";
import Icon from "@/core/components/primitives/icon/icon";
import styles from "./existing-albums-list.module.less";
import { UseQueryResult } from "@tanstack/react-query";
import { motion } from "framer-motion";
import { OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import { DateHelper, multipleClassNames } from "@/core/helpers";
import { AlbumResponse } from "@parksandresorts/webapiproxy-types";
import { albumIdWithHyphens, isAlbumUnlocked } from "../../helpers";

export type Album = {
  id: string;
  query: UseQueryResult<AlbumResponse, Error>;
};

type CommonProps = {
  albums: Array<Album>;
  albumIdInLoadingState?: string;
  albumIdInErrorState?: string;
  onClick: (albumId: string) => void;
  addToAlbumMediaAmount?: number;
};

export type Props = CommonProps &
  (
    | {
        action: "ADD_TO_ALBUM";
        visitDate: string;
      }
    | {
        action: "GO_TO_ALBUM";
        visitDate?: never;
      }
  );

export const ExistingAlbumsList = ({
  albums,
  action,
  albumIdInLoadingState,
  albumIdInErrorState,
  onClick,
  addToAlbumMediaAmount,
  visitDate,
}: Props) => {
  const { t } = useTranslation();
  return (
    <div className={styles.wrapper} data-testid="digital-ride-media-existing-albums-list">
      <ul>
        {albums.map(({ id: albumIdOfThisQuery, query: { isLoading, data, isError } }, index) => {
          const isThisAlbumLoading = albumIdInLoadingState === albumIdOfThisQuery;
          const isThisAlbumErrorAfterFetching = albumIdInErrorState === albumIdOfThisQuery;
          const isThisAlbumUnlocked = isAlbumUnlocked(data?.item);
          const albumVisitDate = data?.item?.visitDate;
          const hasVisitDateMismatch = !!visitDate && !DateHelper.isEqualYYYYMMDD(visitDate, albumVisitDate);
          return (
            <li
              key={index}
              data-is-error={isError}
              data-is-unlocked={isThisAlbumUnlocked}
              data-has-visit-date-mismatch={hasVisitDateMismatch}
              data-testid={`digital-ride-media-existing-album-${albumIdWithHyphens(albumIdOfThisQuery)}`}
              onClick={!isError && action === "GO_TO_ALBUM" ? () => onClick(albumIdOfThisQuery) : undefined}
            >
              <motion.div
                className={styles.content}
                data-action-type={action}
                whileHover={
                  !isError && !hasVisitDateMismatch
                    ? {
                        scale: 1.015,
                      }
                    : undefined
                }
                whileTap={
                  !isError && !hasVisitDateMismatch
                    ? {
                        scale: 0.985,
                      }
                    : undefined
                }
              >
                <div className={styles.leftContent}>
                  <div className={styles.nameWrapper}>
                    {isLoading && <SkeletonRectangle />}
                    {data?.item && <h4>{data.item.name}</h4>}
                    {isError && <h4>{t("rideMediaExistingAlbumsErrorMessageHeading")}</h4>}
                  </div>
                  <div className={multipleClassNames(styles.metadataWrapper, "body-xs")}>
                    {isThisAlbumUnlocked && (
                      <div>
                        <p className="bold">{t("rideMediaGeneralAlbumIsUnlocked")}</p>
                        <p data-testid="digital-ride-media-existing-album-save-to-unlocked-album-info">
                          {t("rideMediaExistingAlbumsMetadataSaveMediaToUnlockedAlbumInfo")}
                        </p>
                      </div>
                    )}
                    <div className={styles.metadataInnerWrapper}>
                      <p>{`${t("rideMediaGeneralAlbumCode")}: ${albumIdWithHyphens(albumIdOfThisQuery)}`}</p>
                      {isLoading && <SkeletonRectangle />}
                      {!isLoading && <p>•</p>}
                      {data?.item && (
                        <p
                          data-testid={
                            albumVisitDate
                              ? `digital-ride-media-existing-album-visit-date-${albumIdWithHyphens(albumIdOfThisQuery)}`
                              : `digital-ride-media-existing-album-created-date-${albumIdWithHyphens(
                                  albumIdOfThisQuery,
                                )}`
                          }
                        >
                          {DateHelper.toStringDDMonthYear(albumVisitDate ? albumVisitDate : data.item.created)}
                        </p>
                      )}
                      {isError && <p>{t("rideMediaExistingAlbumsErrorMessageParagraph")}</p>}
                      {hasVisitDateMismatch && <p>{t("rideMediaSearchAlbumFormExistingAlbumsVisitDateNotAMatch")}</p>}
                    </div>
                  </div>
                </div>
                {isThisAlbumLoading && (
                  <div className={styles.actionWrapper}>
                    <Icon name="loading" />
                  </div>
                )}
                {!isError && !isThisAlbumLoading && action === "GO_TO_ALBUM" && (
                  <Icon
                    name="chevron-right"
                    data-testid={`digital-ride-media-existing-album-go-to-album-${albumIdWithHyphens(
                      albumIdOfThisQuery,
                    )}`}
                  />
                )}
                {!isError && !isThisAlbumLoading && !hasVisitDateMismatch && action === "ADD_TO_ALBUM" && (
                  <div className={styles.actionWrapper}>
                    {isThisAlbumUnlocked && !isThisAlbumErrorAfterFetching ? (
                      <PrimaryButton
                        label={t("rideMediaExistingAlbumsMetadataSaveMediaAction", {
                          count: addToAlbumMediaAmount || 1,
                        })}
                        contentfulLabelId="rideMediaExistingAlbumsMetadataSaveMediaAction"
                        onClick={() => onClick(albumIdOfThisQuery)}
                        testId={`digital-ride-media-save-to-existing-unlocked-album-button-${albumIdWithHyphens(
                          albumIdOfThisQuery,
                        )}`}
                      />
                    ) : (
                      <OutlineButton
                        iconRightNew={isThisAlbumErrorAfterFetching ? "error" : undefined}
                        label={
                          isThisAlbumErrorAfterFetching
                            ? `${t("somethingWentWrong")}. ${t("tryAgain")}`
                            : t("rideMediaExistingAlbumsMetadataSaveMediaAction", { count: addToAlbumMediaAmount || 1 })
                        }
                        onClick={() => onClick(albumIdOfThisQuery)}
                        testId={`digital-ride-media-save-to-existing-album-button-${albumIdWithHyphens(
                          albumIdOfThisQuery,
                        )}`}
                      />
                    )}
                  </div>
                )}
              </motion.div>
            </li>
          );
        })}
      </ul>
    </div>
  );
};
