import React, { Fragment } from "react";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import InputField from "@/core/components/primitives/input-field/input-field";
import InputError from "@/core/components/primitives/input-error/input-error";
import InputLabel from "@/core/components/primitives/input-label/input-label";
import styles from "./search-album-form.module.less";
import { useQuery } from "@tanstack/react-query";
import { useCallback, useEffect, useMemo, useRef, useState, RefObject } from "react";
import { IDigitalRideMediaService } from "@/core/services";
import { ExistingAlbumsList, Props as ExistingAlbumsListProps } from "../existing-albums-list/existing-albums-list";
import { useTranslation } from "react-i18next";
import { debounce } from "lodash-es";
import { Translation } from "@/core/labels/i18n";
import { isNonEmptyArray } from "@/core/helpers";
import { ALBUM_ID_PART_LENGTH } from "../../helpers";

type Props = {
  service: IDigitalRideMediaService;
  onClickAlbumResult: (albumId: string) => void;
  albumIdInLoadingState?: string;
  albumIdInErrorState?: string;
  addToAlbumMediaAmount?: number;
  albumAction:
    | {
        action: "ADD_TO_ALBUM";
        /** Visit date for media to save, has to match album visit date */
        visitDate: string;
      }
    | {
        action: "GO_TO_ALBUM";
      };
};

/**
 * Validates a single album ID part against the expected length.
 * @returns An error message if invalid, or `undefined` if valid.
 */
const checkAlbumIdPart = (t: Translation, value: string) => {
  if (value.length !== ALBUM_ID_PART_LENGTH) {
    return t("rideMediaSearchAlbumFormWrongCodeLenght");
  }
  return undefined;
};

/** Configuration for a single album ID input field. */
type AlbumIdField = {
  id: string;
  testId: string;
  /** Ref to this field's input element (used by the previous field to focus forward). */
  inputRef?: RefObject<HTMLInputElement>;
  /** Ref to the next focusable element, auto-focused when this field reaches the correct length. */
  focusNextRef?: RefObject<HTMLInputElement | HTMLButtonElement>;
};

export const SearchAlbumForm = ({
  service,
  onClickAlbumResult,
  albumIdInLoadingState,
  albumIdInErrorState,
  addToAlbumMediaAmount,
  albumAction,
}: Props) => {
  const { t } = useTranslation();

  const [albumIdParts, setAlbumIdParts] = useState<Record<string, string>>({});

  const secondInputRef = useRef<HTMLInputElement>(null);
  const thirdInputRef = useRef<HTMLInputElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  /** Field configuration for each album ID segment. Defines focus chain and test IDs. */
  const albumIdFields: Array<AlbumIdField> = useMemo(
    () => [
      {
        id: "albumIdPart1",
        testId: "digital-ride-media-search-album-form-album-code-first-part",
        focusNextRef: secondInputRef,
      },
      {
        id: "albumIdPart2",
        testId: "digital-ride-media-search-album-form-album-code-second-part",
        inputRef: secondInputRef,
        focusNextRef: thirdInputRef,
      },
      {
        id: "albumIdPart3",
        testId: "digital-ride-media-search-album-form-album-code-third-part",
        inputRef: thirdInputRef,
        focusNextRef: buttonRef,
      },
    ],
    [],
  );

  const [error, setError] = useState<Array<{ inputId: string; message: string }>>();

  const [albumIdToSearch, setAlbumIdToSearch] = useState<string>("");

  /** Validates a single field and updates the error state. */
  const validateField = useCallback(
    (value: string, inputId: string) => {
      const potentialErrorMessageForNewValue = checkAlbumIdPart(t, value);

      setError((prevError) => {
        const newErrorWithoutCurrentInput = prevError?.filter((error) => error.inputId !== inputId) || [];

        if (potentialErrorMessageForNewValue) {
          return [...newErrorWithoutCurrentInput, { inputId, message: potentialErrorMessageForNewValue }];
        } else {
          return newErrorWithoutCurrentInput;
        }
      });
    },
    [t],
  );

  /**
   * One debounced validator per field, so typing in one field doesn't
   * cancel or reset the pending validation of another field.
   */
  const debouncedValidateField = useMemo(
    () =>
      new Map(
        albumIdFields.map((field) => [field.id, debounce((value: string) => validateField(value, field.id), 5000)]),
      ),
    [validateField, albumIdFields],
  );

  /** Cleanup: cancel pending debounced validations on unmount. */
  useEffect(() => {
    return () => {
      debouncedValidateField.forEach((debounced) => debounced.cancel());
    };
  }, [debouncedValidateField]);

  /**
   * Validates a field on change. If the value has the correct length, validates immediately
   * and cancels any pending debounce. Otherwise, defers validation via debounce.
   */
  const checkAlbumIdPartValue = (value: string, inputId: string) => {
    const isCorrectLength = value.length === ALBUM_ID_PART_LENGTH;
    if (isCorrectLength) {
      debouncedValidateField.get(inputId)?.cancel();
      validateField(value, inputId);
    } else {
      debouncedValidateField.get(inputId)?.(value);
    }
  };

  /** Overwritten in Contentful for each park */
  const codePrefix = t("rideMediaSearchAlbumFormCodePrefix");
  const albumIdInput = `${codePrefix}${albumIdFields.map((field) => albumIdParts[field.id] ?? "").join("")}`;

  // eslint-disable-next-line @tanstack/query/exhaustive-deps
  const albumMetadataQuery = useQuery({
    queryKey: ["album-metadata", albumIdToSearch],
    enabled: !!albumIdToSearch,
    queryFn: () => service.fetchAlbum(albumIdToSearch),
  });

  /** Validates all fields synchronously. Used on form submission. Returns `true` if all fields are valid. */
  const validateAllFields = () => {
    const errors = albumIdFields
      .map(({ id }) => {
        const message = checkAlbumIdPart(t, albumIdParts[id] ?? "");
        return message ? { inputId: id, message } : undefined;
      })
      .filter((e): e is { inputId: string; message: string } => !!e);

    setError(errors);
    return errors.length === 0;
  };

  const isInputValid = (inputId: string) => {
    return !(error && error.some((error) => error.inputId === inputId));
  };

  /**
   * Handles pasting a full album code (e.g. "GRO-TOD-NON-PEN" or "GROTODNONPEN") into any input field.
   * Accepts the code with or without hyphens. If the pasted text matches the expected prefix and
   * total length, it prevents the default paste and distributes each part to the corresponding field.
   * If the format doesn't match, the paste proceeds normally and triggers onChange.
   */
  const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
    const pastedText = e.clipboardData.getData("text").trim().toUpperCase().replaceAll("-", "");
    const prefix = codePrefix.toUpperCase();
    const expectedLength = prefix.length + ALBUM_ID_PART_LENGTH * albumIdFields.length;

    if (pastedText.length !== expectedLength || !pastedText.startsWith(prefix)) {
      return;
    }

    e.preventDefault();
    const codeBody = pastedText.slice(prefix.length);
    const newAlbumIdParts: Record<string, string> = {};
    albumIdFields.forEach((field, index) => {
      const part = codeBody.slice(index * ALBUM_ID_PART_LENGTH, (index + 1) * ALBUM_ID_PART_LENGTH);
      newAlbumIdParts[field.id] = part;
      checkAlbumIdPartValue(part, field.id);
    });
    setAlbumIdParts(newAlbumIdParts);
    buttonRef.current?.focus();
  };

  const shouldShowExistingAlbumsList = !!albumIdToSearch;

  // Narrow on `props` so TypeScript keeps the link between action and
  // visitDate (destructuring them into separate variables breaks that link).
  const existingAlbumsListProps: ExistingAlbumsListProps = {
    albums: [{ id: albumIdToSearch, query: albumMetadataQuery }],
    albumIdInLoadingState,
    albumIdInErrorState,
    onClick: onClickAlbumResult,
    addToAlbumMediaAmount,
    ...(albumAction.action === "ADD_TO_ALBUM"
      ? { action: "ADD_TO_ALBUM", visitDate: albumAction.visitDate }
      : { action: "GO_TO_ALBUM" }),
  };

  return (
    <div className={styles.wrapper}>
      <div className={styles.formWrapper}>
        <div>
          <div className={styles.inputWrapper}>
            <InputLabel
              label={t("rideMediaGeneralAlbumCode")}
              inputName={albumIdFields[0].id}
              id="labelForAlbumIdInput"
              isRequired={true}
            />
            <InputField
              value={codePrefix}
              size={codePrefix.length}
              className={styles.lockedInputPrefix}
              icon="lock"
              readOnly
              focus={false}
              aria-labelledby="labelForAlbumIdInput"
            />
            {albumIdFields.map((field) => (
              <Fragment key={field.id}>
                <p className={styles.hyphen}>-</p>
                <InputField
                  inputRef={field.inputRef}
                  name={field.id}
                  className={styles.input}
                  placeholder="XXX"
                  isValid={isInputValid(field.id)}
                  value={albumIdParts[field.id]}
                  onChange={(_name, value) => {
                    if (value.length === ALBUM_ID_PART_LENGTH) {
                      field.focusNextRef?.current?.focus();
                    }
                    checkAlbumIdPartValue(value, field.id);
                    setAlbumIdParts((prev) => ({ ...prev, [field.id]: value.toUpperCase() }));
                  }}
                  onPaste={handlePaste}
                  data-testid={field.testId}
                />
              </Fragment>
            ))}
          </div>
          <InputError
            showError={isNonEmptyArray(error)}
            errorText={isNonEmptyArray(error) ? error[0].message : undefined}
            data-testid="digital-ride-media-search-album-form-error"
          />
        </div>
        <PrimaryButton
          ref={buttonRef}
          label={t("rideMediaSearchAlbumFormSearchButton")}
          className={styles.button}
          isFullWidth
          onClick={() => {
            debouncedValidateField.forEach((debounced) => debounced.cancel());
            if (!validateAllFields()) {
              return;
            }

            setAlbumIdToSearch(albumIdInput);
          }}
          data-testid="digital-ride-media-search-album-form-search-button"
        />
      </div>
      <div className={styles.resultWrapper}>
        {shouldShowExistingAlbumsList && <ExistingAlbumsList {...existingAlbumsListProps} />}
      </div>
    </div>
  );
};
